custom_css:
.sc-tw :root{
    --gold-haze:       oklch(85% 0.12 70);
    --dust-amber:      oklch(75% 0.15 50);
    --deep-earth:      oklch(22% 0.06 50);
    --obsidian:        oklch(12% 0.03 40);
    --ivory-mist:      oklch(96% 0.03 75);
    --warm-white:      oklch(98% 0.01 80);
    --sienna-mid:      oklch(55% 0.14 50);
    --ochre-glow:      oklch(78% 0.18 68);
    --grass-green:     oklch(55% 0.12 145);
    --predator-dark:   oklch(18% 0.04 45);

    --r-squircle: 38% 62% 63% 37% / 41% 44% 56% 59%;
    --r-lens:     48% 52% 58% 42% / 44% 41% 59% 56%;
    --r-card:     32% 68% 55% 45% / 48% 36% 64% 52%;
    --r-pill:     72% 28% 34% 66% / 55% 62% 38% 45%;

    --blur-haze: blur(80px) saturate(1.5) brightness(0.95);
    --blur-glass: blur(24px) saturate(1.8) brightness(1.05);

    --font-display: 'DM Serif Display', serif;
    --font-title:   'Playfair Display', serif;
    --font-data:    'Space Mono', monospace;
    --font-ui:      'Syne', sans-serif;
  }.sc-tw *,.sc-tw *::before,.sc-tw *::after{ box-sizing: border-box; margin: 0; padding: 0; }.sc-tw html{ scroll-behavior: smooth; overflow-x: hidden; }.sc-tw{
    background: var(--obsidian);
    color: var(--ivory-mist);
    font-family: var(--font-ui);
    overflow-x: hidden;
    cursor: none;
  }.sc-tw #cursor-ring{
    position: fixed; width: 40px; height: 40px;
    border: 1.5px solid oklch(85% 0.12 70 / 0.6);
    border-radius: 50%;
    pointer-events: none; z-index: 9999;
    transform: translate(-50%, -50%);
    transition: width 0.3s, height 0.3s, border-color 0.3s, border-radius 0.3s;
    mix-blend-mode: screen;
  }.sc-tw #cursor-dot{
    position: fixed; width: 6px; height: 6px;
    background: var(--gold-haze);
    border-radius: 50%;
    pointer-events: none; z-index: 9999;
    transform: translate(-50%, -50%);
  }.sc-tw body:has(a:hover) #cursor-ring,.sc-tw body:has(button:hover) #cursor-ring{
    width: 64px; height: 64px;
    border-color: var(--ochre-glow);
    border-radius: 40%;
  }.sc-tw ::-webkit-scrollbar{ width: 3px; }.sc-tw ::-webkit-scrollbar-track{ background: var(--obsidian); }.sc-tw ::-webkit-scrollbar-thumb{
    background: linear-gradient(to bottom, var(--gold-haze), var(--dust-amber));
    border-radius: 99px;
  }.sc-tw body::before{
    content: '';
    position: fixed; inset: 0; z-index: 1;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
    opacity: 0.035;
    pointer-events: none;
  }.sc-tw .light-corridor{
    position: fixed; inset: 0; z-index: 0; pointer-events: none;
    background:
      radial-gradient(ellipse at center, oklch(85% 0.12 70 / 0.3) 0%, oklch(75% 0.15 50 / 0.1) 50%, transparent 85%);
    backdrop-filter: blur(120px) contrast(1.1);
    animation: corridor-breathe 8s ease-in-out infinite alternate;
  }
  @keyframes corridor-breathe {0%{ opacity: 0.6; transform: scale(1) translateY(0); }100%{ opacity: 1;   transform: scale(1.08) translateY(-2%); }
  }.sc-tw .dust-field{
    position: fixed; inset: 0; z-index: 0; pointer-events: none; overflow: hidden;
  }.sc-tw .dust-field span{
    position: absolute;
    width: 2px; height: 2px;
    background: var(--gold-haze);
    border-radius: 50%;
    animation: dust-drift linear infinite;
    opacity: 0;
  }
  @keyframes dust-drift {0%{ transform: translateY(100vh) translateX(0) scale(0); opacity: 0; }10%{ opacity: 0.6; }90%{ opacity: 0.3; }100%{ transform: translateY(-10vh) translateX(var(--drift-x, 30px)) scale(1.5); opacity: 0; }
  }.sc-tw main{ position: relative; z-index: 2; }.sc-tw nav{
    position: fixed; top: 0; left: 0; right: 0; z-index: 100;
    display: flex; align-items: center; justify-content: space-between;
    padding: 1.5rem 3rem;
    backdrop-filter: blur(40px) saturate(1.4);
    background: oklch(12% 0.03 40 / 0.4);
    border-bottom: 1px solid oklch(85% 0.12 70 / 0.08);
  }.sc-tw .nav-logo{
    display: flex; align-items: center; gap: 0.75rem;
    font-family: var(--font-ui); font-weight: 800; font-size: 0.7rem;
    letter-spacing: 0.25em; text-transform: uppercase;
    color: var(--ivory-mist);
  }.sc-tw .nav-logo .logo-rect{
    width: 36px; height: 24px;
    background: var(--ochre-glow);
    border-radius: 4px 12px 4px 12px;
    flex-shrink: 0;
  }.sc-tw .nav-links{
    display: flex; gap: 2.5rem; list-style: none;
    font-size: 0.68rem; letter-spacing: 0.18em; text-transform: uppercase;
  }.sc-tw .nav-links a{
    color: oklch(85% 0.12 70 / 0.7);
    text-decoration: none;
    transition: color 0.3s;
    position: relative;
  }.sc-tw .nav-links a::after{
    content: '';
    position: absolute; bottom: -4px; left: 0; right: 100%;
    height: 1px;
    background: var(--ochre-glow);
    transition: right 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }.sc-tw .nav-links a:hover{ color: var(--ochre-glow); }.sc-tw .nav-links a:hover::after{ right: 0; }.sc-tw .nav-status{
    display: flex; align-items: center; gap: 0.5rem;
    font-family: var(--font-data); font-size: 0.6rem;
    color: var(--grass-green); letter-spacing: 0.1em;
  }.sc-tw .status-pulse{
    width: 6px; height: 6px;
    background: var(--grass-green);
    border-radius: 50%;
    animation: pulse-live 2s ease-in-out infinite;
    box-shadow: 0 0 8px var(--grass-green);
  }
  @keyframes pulse-live {0%,100%{ transform: scale(1); opacity: 1; }50%{ transform: scale(1.6); opacity: 0.4; }
  }.sc-tw .hero{
    position: relative; min-height: 100vh;
    display: flex; align-items: center;
    overflow: hidden;
    padding: 0 4rem;
  }.sc-tw .savanna-portal{
    position: absolute;
    right: -5%;
    top: 50%;
    transform: translateY(-50%) rotate(-2deg);
    width: 62vw; height: 72vh;
    z-index: 1;
    animation: lens-drift 12s ease-in-out infinite alternate;
  }
  @keyframes lens-drift {0%{ transform: translateY(-50%) rotate(-2deg) scale(1);    right: -5%; }50%{ transform: translateY(-52%) rotate(-1deg) scale(1.02); right: -3%; }100%{ transform: translateY(-48%) rotate(-3deg) scale(0.99); right: -6%; }
  }.sc-tw .portal-mask{
    width: 100%; height: 100%;
    position: relative;
    border-radius: var(--r-lens);
    overflow: hidden;
    box-shadow:
      inset 0 0 80px oklch(85% 0.12 70 / 0.15),
      0 0 120px oklch(75% 0.15 50 / 0.25),
      0 40px 100px oklch(12% 0.03 40 / 0.6);
  }.sc-tw .portal-mask::before{
    content: '';
    position: absolute; inset: -2px; z-index: 3;
    background: transparent;
    border-radius: var(--r-lens);
    box-shadow: inset 0 0 0 3px oklch(85% 0.12 70 / 0.2);
    pointer-events: none;
  }.sc-tw .portal-mask::after{
    content: '';
    position: absolute; inset: 0; z-index: 2;
    background: transparent;
    backdrop-filter: none;
    pointer-events: none;
    border-radius: var(--r-lens);
  }.sc-tw .portal-video{
    width: 100%; height: 100%;
    object-fit: cover;
    filter: none;
    transform: none;
    transition: none;
  }.sc-tw .grass-overlay{
    position: absolute; inset: 0; z-index: 4;
    pointer-events: none;
    background: none;
    opacity: 0;
    border-radius: var(--r-lens);
  }.sc-tw .hero-content{
    position: relative; z-index: 10;
    max-width: 42%;
    padding-top: 6rem;
  }.sc-tw .hero-eyebrow{
    display: flex; align-items: center; gap: 0.75rem;
    font-family: var(--font-data); font-size: 0.62rem;
    letter-spacing: 0.3em; text-transform: uppercase;
    color: var(--ochre-glow); margin-bottom: 1.5rem;
    opacity: 0; animation: fade-up 1s 0.3s forwards;
  }.sc-tw .eyebrow-line{
    width: 40px; height: 1px;
    background: linear-gradient(to right, var(--ochre-glow), transparent);
  }.sc-tw .hero-title{
    font-family: var(--font-display);
    font-size: clamp(3.2rem, 5.5vw, 7rem);
    font-weight: 400; line-height: 0.9;
    color: var(--ivory-mist);
    letter-spacing: -0.02em;
    margin-bottom: 2rem;
    opacity: 0; animation: fade-up 1s 0.5s forwards;
  }.sc-tw .hero-title em{
    font-style: italic;
    color: var(--ochre-glow);
    display: block;
  }.sc-tw .hero-body{
    font-family: var(--font-ui); font-size: 0.88rem;
    line-height: 1.75; font-weight: 400;
    color: oklch(85% 0.12 70 / 0.65);
    max-width: 36ch;
    margin-bottom: 2.5rem;
    opacity: 0; animation: fade-up 1s 0.7s forwards;
  }

  @keyframes fade-up {from{ opacity: 0; transform: translateY(24px); }to{ opacity: 1; transform: translateY(0); }
  }.sc-tw .hero-ctas{
    display: flex; align-items: center; gap: 1.25rem; flex-wrap: wrap;
    opacity: 0; animation: fade-up 1s 0.9s forwards;
  }.sc-tw .btn-primary{
    position: relative; overflow: hidden;
    padding: 0.85rem 2rem;
    background: oklch(85% 0.12 70 / 0.12);
    border: 1px solid oklch(85% 0.12 70 / 0.3);
    border-radius: 44% 56% 38% 62% / 52% 44% 56% 48%;
    color: var(--ivory-mist);
    font-family: var(--font-ui); font-size: 0.72rem;
    font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase;
    cursor: none; text-decoration: none;
    backdrop-filter: var(--blur-glass);
    box-shadow:
      inset 0 1px 0 oklch(85% 0.12 70 / 0.2),
      inset 0 -1px 0 oklch(12% 0.03 40 / 0.3),
      0 8px 32px oklch(12% 0.03 40 / 0.4);
    transition: all 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }.sc-tw .btn-primary::before{
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse at 50% 0%, oklch(85% 0.12 70 / 0.25) 0%, transparent 70%);
    opacity: 0; transition: opacity 0.3s;
  }.sc-tw .btn-primary:hover{ transform: translateY(-2px) scale(1.02); }.sc-tw .btn-primary:hover::before{ opacity: 1; }.sc-tw .btn-ghost{
    display: flex; align-items: center; gap: 0.5rem;
    color: oklch(85% 0.12 70 / 0.55);
    font-family: var(--font-data); font-size: 0.62rem;
    letter-spacing: 0.15em; text-transform: uppercase;
    cursor: none; text-decoration: none;
    transition: color 0.3s;
  }.sc-tw .btn-ghost::after{
    content: '→'; font-size: 1rem;
    transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  }.sc-tw .btn-ghost:hover{ color: var(--ochre-glow); }.sc-tw .btn-ghost:hover::after{ transform: translateX(6px); }.sc-tw .telemetry-hud{
    position: absolute;
    bottom: 2rem; left: 2rem; z-index: 12;
    opacity: 0; animation: fade-up 1s 1.2s forwards;
  }.sc-tw .hud-panel{
    background: oklch(12% 0.03 40 / 0.65);
    backdrop-filter: var(--blur-glass);
    border: 1px solid oklch(85% 0.12 70 / 0.12);
    border-radius: 28% 72% 22% 78% / 42% 32% 68% 58%;
    padding: 1rem 1.4rem;
    font-family: var(--font-data); font-size: 0.58rem;
    color: oklch(85% 0.12 70 / 0.7);
    letter-spacing: 0.1em;
    box-shadow: inset 0 1px 0 oklch(85% 0.12 70 / 0.1);
  }.sc-tw .hud-row{ display: flex; gap: 1.5rem; margin-bottom: 0.3rem; }.sc-tw .hud-row:last-child{ margin: 0; }.sc-tw .hud-label{ color: oklch(55% 0.14 50 / 0.6); }.sc-tw .hud-value{ color: var(--ochre-glow); }.sc-tw .scroll-hint{
    position: absolute; bottom: 2.5rem; left: 50%;
    transform: translateX(-50%);
    display: flex; flex-direction: column; align-items: center; gap: 0.5rem;
    font-family: var(--font-data); font-size: 0.55rem;
    letter-spacing: 0.3em; text-transform: uppercase;
    color: oklch(85% 0.12 70 / 0.3);
    z-index: 10;
    animation: fade-up 1s 1.5s both;
  }.sc-tw .scroll-track{
    width: 1px; height: 48px;
    background: linear-gradient(to bottom, var(--ochre-glow), transparent);
    animation: scroll-pulse 2.5s ease-in-out infinite;
  }
  @keyframes scroll-pulse {0%{ transform: scaleY(0); transform-origin: top; opacity: 0; }50%{ transform: scaleY(1); opacity: 1; }100%{ transform: scaleY(0); transform-origin: bottom; opacity: 0; }
  }.sc-tw .section-glow{
    position: relative;
    padding: 8rem 4rem;
  }.sc-tw .section-glow::before{
    content: '';
    position: absolute; left: 50%; top: 0;
    transform: translateX(-50%);
    width: 60%; height: 1px;
    background: radial-gradient(ellipse at center, oklch(85% 0.12 70 / 0.3) 0%, transparent 70%);
  }.sc-tw .telemetry-section{
    position: relative;
    padding: 7rem 4rem;
    overflow: hidden;
  }.sc-tw .section-label{
    display: flex; align-items: center; gap: 1rem;
    font-family: var(--font-data); font-size: 0.6rem;
    letter-spacing: 0.35em; text-transform: uppercase;
    color: var(--sienna-mid); margin-bottom: 1rem;
  }.sc-tw .section-label-line{
    width: 32px; height: 1px;
    background: var(--sienna-mid);
  }.sc-tw .section-title{
    font-family: var(--font-title);
    font-size: clamp(2.2rem, 4vw, 4.5rem);
    font-weight: 700; line-height: 1;
    color: var(--ivory-mist);
    letter-spacing: -0.02em;
    max-width: 14ch;
    margin-bottom: 4rem;
  }.sc-tw .section-title span{ color: var(--ochre-glow); font-style: italic; }.sc-tw .card-river{
    display: flex; gap: 2rem; flex-wrap: wrap;
    position: relative;
  }.sc-tw .card-river::before{
    content: '';
    position: absolute;
    top: -40px; left: 10%; right: 10%;
    height: 80px;
    background: radial-gradient(ellipse at center, oklch(85% 0.12 70 / 0.06) 0%, transparent 70%);
    pointer-events: none;
  }.sc-tw .tech-card{
    position: relative;
    flex: 1 1 280px; max-width: 360px;
    padding: 2.2rem 2rem;
    background: oklch(18% 0.04 45 / 0.7);
    backdrop-filter: var(--blur-glass);
    border: 1px solid oklch(85% 0.12 70 / 0.08);
    border-radius: var(--r-card);
    overflow: hidden;
    transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.5s;
    cursor: none;
    will-change: transform;
  }.sc-tw .tech-card::before{
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse at 30% 0%, oklch(85% 0.12 70 / 0.08) 0%, transparent 60%);
    opacity: 0;
    transition: opacity 0.4s;
    pointer-events: none;
  }.sc-tw .tech-card::after{
    content: '';
    position: absolute; top: 0; left: 0; right: 0; height: 1px;
    background: linear-gradient(to right, transparent, oklch(85% 0.12 70 / 0.3), transparent);
    opacity: 0.5;
  }.sc-tw .tech-card:hover{
    transform: translateY(-8px) rotate(0.5deg);
    box-shadow: 0 32px 80px oklch(12% 0.03 40 / 0.5), 0 0 0 1px oklch(85% 0.12 70 / 0.15);
  }.sc-tw .tech-card:hover::before{ opacity: 1; }.sc-tw .card-icon{
    width: 48px; height: 48px; margin-bottom: 1.5rem;
    border-radius: 35% 65% 42% 58% / 50% 38% 62% 50%;
    background: oklch(85% 0.12 70 / 0.1);
    border: 1px solid oklch(85% 0.12 70 / 0.15);
    display: flex; align-items: center; justify-content: center;
    font-size: 1.3rem;
    box-shadow: inset 0 0 16px oklch(85% 0.12 70 / 0.1);
  }.sc-tw .card-kicker{
    font-family: var(--font-data); font-size: 0.56rem;
    letter-spacing: 0.25em; text-transform: uppercase;
    color: var(--sienna-mid); margin-bottom: 0.5rem;
  }.sc-tw .card-name{
    font-family: var(--font-title); font-size: 1.3rem;
    font-weight: 700; line-height: 1.1;
    color: var(--ivory-mist); margin-bottom: 0.8rem;
  }.sc-tw .card-desc{
    font-size: 0.8rem; line-height: 1.7;
    color: oklch(85% 0.12 70 / 0.5);
  }.sc-tw .card-metric{
    margin-top: 1.5rem; padding-top: 1rem;
    border-top: 1px solid oklch(85% 0.12 70 / 0.08);
    display: flex; justify-content: space-between; align-items: baseline;
    font-family: var(--font-data); font-size: 0.6rem;
  }.sc-tw .metric-val{ font-size: 1.4rem; color: var(--ochre-glow); font-weight: 700; }.sc-tw .metric-label{ color: oklch(85% 0.12 70 / 0.35); letter-spacing: 0.1em; }.sc-tw .data-strip{
    display: flex; gap: 0; overflow: hidden;
    border-radius: 48px; margin: 3rem 0;
    border: 1px solid oklch(85% 0.12 70 / 0.08);
  }.sc-tw .data-cell{
    flex: 1; padding: 1.5rem;
    border-right: 1px solid oklch(85% 0.12 70 / 0.06);
    background: oklch(16% 0.04 45 / 0.5);
    backdrop-filter: blur(20px);
    text-align: center; position: relative; overflow: hidden;
    transition: background 0.4s, transform 0.4s;
    cursor: none;
  }.sc-tw .data-cell:last-child{ border-right: none; }.sc-tw .data-cell:hover{ background: oklch(20% 0.05 50 / 0.7); }.sc-tw .data-cell::before{
    content: '';
    position: absolute; bottom: 0; left: 10%; right: 10%; height: 2px;
    background: linear-gradient(to right, transparent, var(--ochre-glow), transparent);
    transform: scaleX(0); transition: transform 0.4s;
    transform-origin: center;
  }.sc-tw .data-cell:hover::before{ transform: scaleX(1); }.sc-tw .data-big{
    font-family: var(--font-title); font-size: 2.4rem; font-weight: 900;
    color: var(--ochre-glow); line-height: 1;
    display: block; margin-bottom: 0.25rem;
  }.sc-tw .data-sub{
    font-family: var(--font-data); font-size: 0.55rem;
    letter-spacing: 0.2em; text-transform: uppercase;
    color: oklch(85% 0.12 70 / 0.4);
  }.sc-tw .biome-section{
    position: relative; padding: 7rem 4rem;
    overflow: hidden;
  }.sc-tw .biome-grid{
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 4rem; align-items: center;
  }.sc-tw .biome-visual{
    position: relative; height: 500px;
  }.sc-tw .biome-orb{
    position: absolute;
    border-radius: var(--r-pill);
    animation: orb-float ease-in-out infinite alternate;
  }.sc-tw .biome-orb-1{
    width: 340px; height: 340px; top: 0; left: 0;
    background: radial-gradient(ellipse at 35% 35%, oklch(78% 0.18 68 / 0.15), oklch(22% 0.06 50 / 0.05));
    border: 1px solid oklch(85% 0.12 70 / 0.1);
    backdrop-filter: blur(40px);
    animation-duration: 7s;
    box-shadow: inset 0 0 60px oklch(85% 0.12 70 / 0.06);
  }.sc-tw .biome-orb-2{
    width: 240px; height: 260px; bottom: 0; right: 0;
    background: radial-gradient(ellipse at 60% 60%, oklch(55% 0.12 145 / 0.12), transparent);
    border: 1px solid oklch(55% 0.12 145 / 0.15);
    animation-duration: 9s;
  }.sc-tw .biome-orb-3{
    width: 160px; height: 180px; top: 50%; left: 55%;
    transform: translate(-50%, -50%);
    background: radial-gradient(ellipse at center, oklch(75% 0.15 50 / 0.2), transparent);
    animation-duration: 5s;
    border: 1px solid oklch(75% 0.15 50 / 0.2);
    backdrop-filter: blur(20px);
  }
  @keyframes orb-float {0%{ transform: translateY(0) rotate(0deg) scale(1); }100%{ transform: translateY(-20px) rotate(3deg) scale(1.04); }
  }.sc-tw .acoustic-bar-wrap{
    display: flex; align-items: flex-end; gap: 4px;
    height: 80px; margin: 1rem 0;
  }.sc-tw .acoustic-bar{
    flex: 1;
    background: linear-gradient(to top, var(--ochre-glow), oklch(85% 0.12 70 / 0.3));
    border-radius: 99px 99px 0 0;
    animation: wave-pulse 1.4s ease-in-out infinite;
    min-height: 4px;
  }
  @keyframes wave-pulse {0%,100%{ height: var(--bar-h, 30%); }50%{ height: var(--bar-h2, 70%); }
  }.sc-tw .spec-list{
    list-style: none; margin-top: 1.5rem;
  }.sc-tw .spec-list li{
    display: flex; justify-content: space-between; align-items: center;
    padding: 0.65rem 0;
    border-bottom: 1px solid oklch(85% 0.12 70 / 0.06);
    font-size: 0.8rem;
    transition: background 0.2s;
  }.sc-tw .spec-list li:last-child{ border-bottom: none; }.sc-tw .spec-key{ color: oklch(85% 0.12 70 / 0.45); font-family: var(--font-data); font-size: 0.62rem; letter-spacing: 0.1em; }.sc-tw .spec-val{ color: var(--ivory-mist); font-weight: 600; }.sc-tw .spec-badge{
    font-family: var(--font-data); font-size: 0.52rem; letter-spacing: 0.15em;
    padding: 0.2rem 0.5rem;
    border-radius: 99px;
    background: oklch(55% 0.12 145 / 0.15);
    border: 1px solid oklch(55% 0.12 145 / 0.3);
    color: oklch(70% 0.14 145);
  }.sc-tw .genomic-section{
    padding: 7rem 4rem;
    position: relative;
  }.sc-tw .genomic-grid{
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem;
    margin-top: 3rem;
